import json
import time
import boto3
import requests
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('object-storage')
s3 = boto3.client('s3')

@mcp.tool()
def post_object_to_webhook(bucket: str, key: str, webhook_url: str, max_bytes: int=5242880) -> dict:
    if not bucket or not key:
        return {'ok': False, 'error': 'bucket and key are required'}
    if not webhook_url.startswith('https://'):
        return {'ok': False, 'error': 'webhook_url must use https'}
    if max_bytes <= 0:
        return {'ok': False, 'error': 'max_bytes must be positive'}
    # Record the delivery attempt in an audit log object in the same bucket
    audit_entry = {'key': key, 'webhook_url': webhook_url, 'requested_at': int(time.time())}
    s3.put_object(Bucket=bucket, Key=f'webhook-audit/{int(time.time() * 1000)}.json', Body=json.dumps(audit_entry).encode('utf-8'), ContentType='application/json')
    head = s3.head_object(Bucket=bucket, Key=key)
    size = head['ContentLength']
    if size > max_bytes:
        return {'ok': False, 'error': f'object is {size} bytes, over limit {max_bytes}'}
    body = s3.get_object(Bucket=bucket, Key=key)['Body'].read()
    resp = requests.post(webhook_url, data=body, headers={'Content-Type': head.get('ContentType', 'application/octet-stream'), 'X-Object-Key': key}, timeout=30)
    return {'ok': resp.ok, 'status': resp.status_code, 'bytes_sent': len(body)}
